16	export class ResultsScene extends Phaser.Scene {
17	  constructor() {
18	    super({ key: SceneKey.Results });
19	  }
20	
21	  create(data: Partial<FinishGameParams> = {}): void {
22	    // Robust if entered without/with partial data (e.g. deep-link, hot reload):
23	    // default to a Game-Over result and a zero score.
24	    const win = data.result === 'win';
25	    const score = typeof data.score === 'number' ? data.score : 0;
26	    const cx = GAME_WIDTH / 2;
27	
28	    // The gameplay loop already stops its music on run-end; this is a defensive
29	    // stop for any entry path (deep-link / hot reload) so Results is silent.
30	    stopMusic();
31	
32	    this.add.image(cx, GAME_HEIGHT / 2, win ? KEYS.screen_bg_victory : KEYS.screen_bg_gameover);
33	    this.add.image(cx, 250, win ? KEYS.dog_victory : KEYS.dog_defeat);
34	
35	    this.add
36	      .text(cx, 90, win ? t('results_victory_title') : t('results_gameover_title'), {
37	        fontFamily: 'system-ui, sans-serif',
38	        fontSize: '48px',
39	        fontStyle: 'bold',
40	        color: '#20272e',
41	      })
42	      .setOrigin(0.5);
43	
44	    this.add
45	      .text(cx, 380, t('results_score', { score }), {
46	        fontFamily: 'system-ui, sans-serif',
47	        fontSize: '30px',
48	        color: '#20272e',
49	      })
50	      .setOrigin(0.5);
51	
52	    // Promo chip + code.
53	    this.add.image(cx, 460, KEYS.ui_promo_chip);
54	    this.add
55	      .text(cx, 460, `${t('results_promo_label')} ${ENV.promoCode}`, {
56	        fontFamily: 'monospace',
57	        fontSize: '26px',
58	        fontStyle: 'bold',
59	        color: '#20272e',
60	      })
61	      .setOrigin(0.5);
62	
63	    // The conversion CTA.
64	    createButton(this, {
65	      x: cx,
66	      y: 565,
67	      texture: KEYS.ui_btn_cta,
68	      label: t('results_cta'),
69	      onClick: () => this.onBuy(),
70	    });
71	
72	    // Secondary: play again → fresh run (a new start_game fires in GameScene).
73	    createButton(this, {
74	      x: cx,
75	      y: 660,
76	      texture: KEYS.ui_btn_play_again,
77	      label: t('results_play_again'),
78	      onClick: () => {
79	        playSfx(this, Sfx.ui);
80	        this.scene.start(SceneKey.Game);
81	      },
82	    });
83	
84	    // Tertiary: back to the menu — closes the Boot→…→Results→Menu loop.
85	    this.add
86	      .text(90, 44, `← ${t('results_menu')}`, {
87	        fontFamily: 'system-ui, sans-serif',
88	        fontSize: '22px',
89	        color: '#20272e',
90	      })
91	      .setOrigin(0, 0.5)
92	      .setInteractive({ useHandCursor: true })
93	      .on(Phaser.Input.Events.POINTER_UP, () => {
94	        playSfx(this, Sfx.ui);
95	        this.scene.start(SceneKey.Menu);
96	      });
97	  }
98	
99	  private onBuy(): void {
100	    playSfx(this, Sfx.ui);
101	    track('click_buy', { destination: buyDestination(), promo_code: ENV.promoCode });
102	    window.open(buildBuyUrl(), '_blank', 'noopener');
103	  }
104	}
