1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
4	import { KEYS } from '../config/assetManifest';
5	import { t } from '../i18n/strings';
6	import { createButton } from '../ui/Button';
7	import { AudioManager } from '../systems/AudioManager';
8	import { ENV } from '../config/env';
9	import { playSfx, playMusic, Sfx, Music } from '../systems/audio';
10	
11	/**
12	 * MenuScene — title, Play (→ Game), and a persisted mute toggle. Fires no
13	 * analytics (start_game fires when the run actually begins, in GameScene).
14	 */
15	export class MenuScene extends Phaser.Scene {
16	  constructor() {
17	    super({ key: SceneKey.Menu });
18	  }
19	
20	  create(): void {
21	    const cx = GAME_WIDTH / 2;
22	
23	    // Drive the browser tab title from i18n (single localized source for the
24	    // game name). The on-canvas title is the `ui_title_logo` asset — we do NOT
25	    // draw `menu_title` over the logo (that would overlap the placeholder).
26	    document.title = t('menu_title');
27	
28	    this.add.image(cx, GAME_HEIGHT / 2, KEYS.screen_bg_menu);
29	    this.add.image(cx, 180, KEYS.ui_title_logo);
30	
31	    this.add
32	      .text(cx, 330, t('menu_subtitle'), {
33	        fontFamily: 'system-ui, sans-serif',
34	        fontSize: '24px',
35	        color: '#3a444d',
36	      })
37	      .setOrigin(0.5);
38	
39	    createButton(this, {
40	      x: cx,
41	      y: 450,
42	      texture: KEYS.ui_btn_play,
43	      label: t('menu_play'),
44	      onClick: () => {
45	        playSfx(this, Sfx.ui);
46	        this.scene.start(SceneKey.Game);
47	      },
48	    });
49	
50	    this.add
51	      .text(cx, 550, t('menu_hint'), {
52	        fontFamily: 'system-ui, sans-serif',
53	        fontSize: '20px',
54	        color: '#3a444d',
55	      })
56	      .setOrigin(0.5);
57	
58	    // Promo teaser chip — the same code the results CTA rewards (spec §6.4).
59	    this.add.image(cx, 648, KEYS.ui_promo_chip);
60	    this.add
61	      .text(cx, 648, `${t('results_promo_label')} ${ENV.promoCode}`, {
62	        fontFamily: 'monospace',
63	        fontSize: '24px',
64	        fontStyle: 'bold',
65	        color: '#20272e',
66	      })
67	      .setOrigin(0.5);
68	
69	    this.buildMuteToggle();
70	
71	    // Menu loop music. Honors the persisted mute (global sound.mute) and the iOS
72	    // unlock installed in BootScene; on first load it plays once the user taps.
73	    playMusic(this, Music.menu);
74	  }
75	
76	  private buildMuteToggle(): void {
77	    const muteBtn = this.add
78	      .image(GAME_WIDTH - 52, 52, this.muteTexture())
79	      .setInteractive({ useHandCursor: true });
80	
81	    const label = this.add
82	      .text(GAME_WIDTH - 52, 90, this.muteLabel(), {
83	        fontFamily: 'system-ui, sans-serif',
84	        fontSize: '14px',
85	        color: '#9fb0bd',
86	      })
87	      .setOrigin(0.5, 0);
88	
89	    muteBtn.on(Phaser.Input.Events.POINTER_UP, () => {
90	      AudioManager.toggle(this.sound);
91	      muteBtn.setTexture(this.muteTexture());
92	      label.setText(this.muteLabel());
93	      playSfx(this, Sfx.ui);
94	    });
95	  }
96	
97	  private muteTexture(): string {
98	    return AudioManager.isMuted() ? KEYS.ui_btn_mute_off : KEYS.ui_btn_mute_on;
99	  }
100	
101	  private muteLabel(): string {
102	    return AudioManager.isMuted() ? t('menu_sound_off') : t('menu_sound_on');
103	  }
104	}
